// Native-only touches for the Android app (AR-3..AR-5, AR-20). main.ts imports this module dynamically,
// only in the capacitor-mode build and only when Capacitor.isNativePlatform(), so the web build
// never contains it, the plugins it uses or Capacitor itself.
// The splash screen and launcher icon are native resources, generated by @capacitor/assets (AR-5).
import { offerAppUpdate } from './app-update'
import { listenToBackButton } from './back-button'
import { followThemeInStatusBar } from './status-bar'

// each touch on its own: one that fails is reported and doesn't stop the others
export async function startNative() {
  followThemeInStatusBar()
  await listenToBackButton().catch((error: unknown) =>
    console.warn('Back button listener failed', error),
  )
  // not awaited: Play's update check needs the network and must not hold up the app
  offerAppUpdate().catch((error: unknown) => console.warn('App update check failed', error))
}
